import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateFrom = req.getParameter("from");
        String dateTo = req.getParameter("to");
        String sortCol = req.getParameter("sort");
        String department = req.getParameter("dept");

        // Validate report type against allowed list
        if (!isValidReportType(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Date validation
        if (!isValidDate(dateFrom) || !isValidDate(dateTo)) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Sort column - only allow known columns
        if (sortCol == null || !sortCol.matches("^[a-zA-Z_]{1,30}$")) {
            sortCol = "created_at";
        }

        // Build query - department is used in WHERE clause
        String query = buildReportQuery(reportType, dateFrom, dateTo, sortCol, department);

        log.info("Executing report query for type=" + reportType + " dept=" + department);

        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.print("{");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) out.print(",");
                    out.print("\"" + meta.getColumnName(i) + "\":");
                    out.print("\"" + escapeJson(rs.getString(i)) + "\"");
                }
                out.print("}");
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildReportQuery(String type, String from, String to, 
                                     String sort, String dept) {
        String baseTable = getTableForReport(type);
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT * FROM ").append(baseTable);
        sb.append(" WHERE created_at >= '").append(from).append("'");
        sb.append(" AND created_at <= '").append(to).append("'");
        if (dept != null && !dept.isEmpty()) {
            sb.append(" AND department = '").append(dept).append("'");
        }
        sb.append(" ORDER BY ").append(sort).append(" LIMIT 1000");
        return sb.toString();
    }

    private String getTableForReport(String type) {
        switch(type) {
            case "sales": return "v_report_sales";
            case "inventory": return "v_report_inventory";
            case "headcount": return "v_report_headcount";
            default: return "v_report_sales";
        }
    }

    private boolean isValidReportType(String type) {
        return type != null && (type.equals("sales") || 
               type.equals("inventory") || type.equals("headcount"));
    }

    private boolean isValidDate(String d) {
        return d != null && d.matches("^\\d{4}-\\d{2}-\\d{2}$");
    }

    private String escapeJson(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("\"", "\\\"");
    }
}
